"""Local browser workbench; all untrusted content is rendered as plain text."""

PAGE = '''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>GResearchEvolver · Agent 工作台</title>
<style>
:root{color-scheme:light;--ink:#163840;--muted:#536e75;--line:#ccdcd9;--paper:#fff;--accent:#006d65}
*{box-sizing:border-box}body{margin:0;background:#eef4f1;color:var(--ink);font:15px/1.6 system-ui,sans-serif}header{padding:24px 4%;background:#103e3b;color:white;display:flex;justify-content:space-between;gap:20px;align-items:center}h1{margin:0;font-size:25px}h2{font-size:18px;margin:0 0 12px}header p{margin:6px 0 0;color:#c9e2dc}header a{color:#dcf7ed}main{max-width:1500px;margin:auto;padding:24px;display:grid;grid-template-columns:340px minmax(0,1fr);gap:22px}.card{background:var(--paper);padding:20px;border:1px solid var(--line);border-radius:12px;margin-bottom:18px}label{display:block;font-weight:600;margin:12px 0 4px}button,input,select,textarea{font:inherit;border-radius:6px;border:1px solid #a7c0b8;padding:8px;max-width:100%}textarea,input,select{width:100%;background:white;color:var(--ink)}textarea{min-height:110px;resize:vertical}button{cursor:pointer;background:#edf6f1;margin:5px 5px 5px 0}button.primary{background:var(--accent);color:white}button:disabled{opacity:.55;cursor:wait}.actions{display:flex;flex-wrap:wrap;gap:4px}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:560px;overflow:auto;font:14px/1.7 ui-monospace,monospace;background:#f4f8f6;padding:14px;border-radius:7px}small,.muted{color:var(--muted)}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:12px 0}.metric{padding:12px;background:#edf6f2;border-radius:8px}.metric b{display:block;font-size:22px}.badge{background:#dfefe7;padding:4px 12px;border-radius:20px}#notice{position:sticky;top:0;padding:8px;background:#fff6d9;display:none;z-index:2}.row{display:flex;gap:12px;align-items:center}.row>*{min-width:0}details{margin:12px 0}summary{cursor:pointer;font-weight:600}.timeline{max-height:350px;overflow:auto}.event{border-left:3px solid #8cbbb0;margin:12px 0;padding-left:12px}.event small{display:block}a{color:var(--accent)}@media(max-width:900px){main{display:block}.metrics{grid-template-columns:repeat(2,1fr)}header{align-items:start}}
.badge{white-space:nowrap;flex-shrink:0}.row{align-items:flex-start}#objective{flex:1;overflow-wrap:anywhere}
</style><header><div><h1>GResearchEvolver · Agent 工作台</h1><p>从研究问题出发，保留证据、过程与人的判断。</p></div><a href="/">完整工作流控制台 →</a></header><div id="notice" role="status"></div>
<main><aside><section class="card"><h2>研究会话</h2><select id="sessions" aria-label="研究会话"></select><button id="refresh">刷新</button><details open><summary>创建新研究</summary>
<label for="goal">研究目标与成功标准</label><textarea id="goal" placeholder="例如：分析不可靠信息下的事件研判，比较来源依赖与证据修订，并给出可验证的实验设计。"></textarea>
<label for="review">介入方式</label><select id="review"><option value="milestones">关键取舍介入，完整草案后审阅</option><option value="every-stage">每个阶段报告后暂停审阅</option></select>
<details><summary>跨会话长期研究</summary><label for="project-id">项目 ID（留空创建普通会话）</label><input id="project-id" placeholder="unreliable-information"><label for="constraints">项目约束（每行一条）</label><textarea id="constraints" placeholder="例如：不把来源转载次数视为独立证据"></textarea><label for="project-budget">整个项目的累计预算 JSON</label><textarea id="project-budget">{"model_calls":120,"tool_calls":400,"active_seconds":14400,"output_tokens":240000,"input_chars":12000000,"external_cost":0}</textarea><button id="project-create">用上述目标创建长期项目</button><small>先创建项目，再创建下方会话；填写已有项目 ID 可续接。所有会话共用预算，科学结论默认等待实际人工审阅。</small></details>
<details><summary>模型与预算</summary><small>密钥通过现有配置或环境变量读取。</small><label for="config">模型配置 JSON</label><textarea id="config">{"provider":"codex-config","max_output_tokens":2000,"timeout":120}</textarea><label for="budget">预算 JSON（未填项使用默认上限）</label><textarea id="budget">{"model_calls":24,"tool_calls":80,"active_seconds":1800,"output_tokens":48000}</textarea><label for="network"><input id="network" type="checkbox" checked style="width:auto"> 允许已注册的公开文献检索</label></details><button class="primary" id="create">创建会话</button></details></section>
<section class="card"><h2>研究材料</h2><small>先选择会话；上传副本并记录哈希。运行时请先暂停。</small><input id="upload" type="file" aria-label="选择研究材料"><button id="import">导入材料</button><select id="files" aria-label="研究产物"></select><button id="read">查看文本</button><a id="download" href="#">下载产物</a></section>
<section class="card"><h2>完整能力目录</h2><p id="count" class="muted"></p><details><summary>技能、工具及介入要求</summary><pre id="catalog"></pre></details></section></aside>
<article><section class="card"><div class="row"><h2 id="objective">选择或创建研究会话</h2><span class="badge" id="status">未开始</span></div><div class="metrics" id="metrics"></div>
<div class="actions"><button class="primary" data-action="run">开始执行</button><button data-action="pause">暂停</button><button data-action="resume">继续</button><button data-action="cancel">取消</button><button data-action="recover">检查并恢复中断</button><button id="fork">按左侧预算续接新会话</button></div><p id="status-help" class="muted"></p><small>暂停在调用边界生效；取消请求停止活动进程。状态不明的外部操作需对账。</small>
<details><summary>中断后的人工对账</summary><p>仅在已检查本地及远程副作用、确认清理后填写。不能凭勾选证明清理完成。</p><textarea id="reconciliation" placeholder='{"actor":"研究者姓名","reason":"核查过程","effects_checked":"实际检查的进程、文件或远程任务及结果"}'></textarea><button id="reconcile">提交对账并恢复</button></details></section>
<section class="card" id="review-card"><h2>研究者决定与反馈</h2><pre id="waiting">当前没有待决定事项。</pre><label for="actor">研究者</label><input id="actor" value="researcher"><label for="decision">意见</label><select id="decision"><option value="answer">回答问题</option><option value="approve">接受报告／批准当前调用</option><option value="reject">拒绝当前请求</option><option value="revise">要求修改并暂停</option><option value="comment">记录意见</option><option value="stop">停止</option></select><label for="reason">判断、理由或修改意见</label><textarea id="reason"></textarea><button id="feedback">提交所显示版本的反馈</button><small>批准绑定当前调用与工作区快照；不会替代科学验证。</small></section>
<section class="card"><h2>随时补充研究方向</h2><label for="direction">新增约束、修改意见或需要澄清的知识点</label><textarea id="direction"></textarea><button id="steer">提交方向并在调用结束后暂停</button><small>未执行的旧计划会撤回；继续后根据这条真实反馈调整。</small></section>
<section class="card"><h2>阶段报告与讲解</h2><select id="reports" aria-label="阶段报告"></select><button id="report-read">读取报告</button><pre id="report"></pre></section>
<section class="card" id="project-card"><h2>长期项目：目标、路线与实验</h2><pre id="project-summary">当前未关联长期项目。</pre><label for="decision-target">本次决定作用于</label><select id="decision-target"><option value="">整个项目</option></select><button id="project-decide">将上方方向意见记入项目并暂停相关会话</button><details><summary>等待已有实验</summary><label for="job-run">已创建的工作流 ID</label><input id="job-run"><label for="job-cost">为该工作流预留成本</label><input id="job-cost" type="number" min="0" value="0"><button id="project-track">登记并执行工作流</button><button id="project-watch">检查结果并继续观察</button><small>等待时只读取运行回执，不调用模型。失败、人工暂停或状态不明时先处理，产物不会伪造。</small></details><details><summary>历史上下文原文</summary><select id="epochs" aria-label="历史上下文"></select><button id="context-read">读取归档</button><button id="context-next">下一页</button><pre id="context-text"></pre></details></section>
<section class="card"><h2>调用进度</h2><div id="timeline" class="timeline"></div><details><summary>模型回复</summary><pre id="answer"></pre></details><details><summary>运行报告与用量</summary><pre id="run-report"></pre></details><details><summary>原始审计记录</summary><pre id="audit"></pre></details><details><summary>调用日志</summary><select id="attempts" aria-label="调用日志"></select><button id="logs">读取日志</button><pre id="logs-text"></pre></details></section>
<section class="card"><h2>产物预览</h2><pre id="artifact"></pre></section></article></main>
<script>
const token=__TOKEN__,el=id=>document.getElementById(id);let current=null,shown=null,fetching=false,projectPins={},contextOffset=0;
const labels={ready:'待执行',running:'运行中',paused:'已暂停',awaiting_researcher:'等待研究者',completed:'执行完成',failed:'失败待检查',interrupted:'中断待对账',cancelled:'已取消',budget_exhausted:'预算已用尽',project_budget_exhausted:'项目累计预算已用尽',waiting_external:'等待实际实验结果',context_exhausted:'必保留信息已达上下文上限'};
function show(id,x){el(id).textContent=typeof x==='string'?x:JSON.stringify(x,null,2)}
function opts(id,items){let previous=el(id).value;el(id).replaceChildren(...items.map(x=>{let o=document.createElement('option');o.value=x.value;o.textContent=x.label;return o}));if(items.some(x=>x.value===previous))el(id).value=previous}
function notice(x){show('notice',x);el('notice').style.display='block'}
async function api(path,body){let r=await fetch('/api/agent/'+path,body?{method:'POST',headers:{'Content-Type':'application/json','X-Research-Token':token},body:JSON.stringify(body)}:{});let x=await r.json();if(!r.ok)throw Error(x.error||r.statusText);return x}
function guarded(fn){return async()=>{try{await fn()}catch(e){notice(e.message)}}}
function sid(){let s=el('sessions').value;if(!s)throw Error('请先创建会话');return s}
function query(){return '?session='+encodeURIComponent(sid())}
async function refresh(){if(fetching)return;fetching=true;try{let sessions=await api('sessions');opts('sessions',sessions.map(s=>({value:s.id,label:(labels[s.status]||s.status)+' · '+s.objective.slice(0,32)})));if(!el('sessions').value)return;let data=await api('session'+query());current=data.state;show('objective',current.objective);show('status',labels[current.status]||current.status);el('metrics').replaceChildren(...[['模型调用',current.usage.model_calls+'/'+current.budget.model_calls],['工具调用',current.usage.tool_calls+'/'+current.budget.tool_calls],['已报告输出 token',current.usage.reported_output_tokens],['阶段报告',current.reports.length]].map(([label,value])=>{let d=document.createElement('div');d.className='metric';let b=document.createElement('b');b.textContent=value;d.append(b,document.createTextNode(label));return d}));
el('feedback').disabled=!current.waiting;
projectPins=data.project_note_pins||{};show('project-summary',data.project||'当前未关联长期项目。');opts('decision-target',[{value:'',label:'整个项目'},...Object.values(data.project?.notes||{}).map(n=>({value:n.id,label:n.kind+' · '+n.id+' · '+n.text.slice(0,60)}))]);opts('epochs',[...(current.parent?.archive_hash?[{value:'0',label:'父会话完整归档'}]:[]),...(current.context_archives||[]).map(a=>({value:String(a.epoch),label:'第 '+a.epoch+' 次归档 · '+a.sha256.slice(0,12)}))]);
if(JSON.stringify(shown)!==JSON.stringify(current.waiting)){shown=current.waiting;show('waiting',shown||'当前没有待决定事项。');if(shown)el('decision').value=['approval','report','scientific_review'].includes(shown.kind)?'approve':shown.kind==='external'?'comment':'answer'}
show('status-help',['budget_exhausted','context_exhausted'].includes(current.status)?'本会话已到上限，原始记录完整保留。可明确设置新预算，续接材料与阶段报告。':'');
opts('files',Object.keys(data.files).map(x=>({value:x,label:x})));download();opts('reports',current.reports.map(x=>({value:x.id,label:x.stage+' · '+x.id})));show('run-report',data.report);show('answer',current.final||current.turns.at(-1)?.text||'模型尚未返回文本。');show('audit',data.events);
el('timeline').replaceChildren(...Object.values(current.calls).sort((a,b)=>(a.sequence||0)-(b.sequence||0)).slice(-20).reverse().map(c=>{let d=document.createElement('div');d.className='event';d.textContent=c.name+' · '+c.status;let sm=document.createElement('small');sm.textContent=c.id+' · '+JSON.stringify(c.arguments).slice(0,220);d.append(sm);return d}));opts('attempts',current.attempts.map(x=>({value:x.directory,label:x.kind+' · '+(x.ok?'完成':'失败')+' · '+(x.call_id||x.directory.slice(0,8))})));if(current.last_error)notice(JSON.stringify(current.last_error));}finally{fetching=false}}
function download(){el('download').href='/api/agent/download'+query()+'&path='+encodeURIComponent(el('files').value)}
async function action(action,extra={}){await api('action',{session:sid(),action,...extra});await refresh()}
el('refresh').onclick=guarded(refresh);el('sessions').onchange=guarded(async()=>{shown=null;show('report','');await refresh()});el('files').onchange=guarded(download);
el('create').onclick=guarded(async()=>{let r=await api('action',{action:'create',objective:el('goal').value,config:JSON.parse(el('config').value),budget:JSON.parse(el('budget').value),long_project:el('project-id').value.trim(),policy:{review_mode:el('review').value,network:el('network').checked}});await refresh();el('sessions').value=r.id;await refresh()});
el('project-create').onclick=guarded(async()=>{let r=await api('action',{action:'project-create',project:el('project-id').value.trim(),objective:el('goal').value,constraints:el('constraints').value.split(String.fromCharCode(10)).map(s=>s.trim()).filter(Boolean),budget:JSON.parse(el('project-budget').value),actor:el('actor').value});notice('长期项目 '+r.id+' 已创建，可创建关联会话。')});
el('project-decide').onclick=guarded(()=>action('project-decide',{text:el('direction').value,actor:el('actor').value,target:el('decision-target').value,expected_hash:projectPins[el('decision-target').value]}));
el('project-track').onclick=guarded(()=>action('project-track',{run:el('job-run').value.trim(),cost:Number(el('job-cost').value),actor:el('actor').value}));
el('project-watch').onclick=guarded(()=>action('project-watch'));
async function readContext(offset){let x=await api('context'+query()+'&epoch='+encodeURIComponent(el('epochs').value)+'&offset='+offset);show('context-text',x.text);contextOffset=x.next_offset;el('context-next').disabled=contextOffset===null}
el('context-read').onclick=guarded(()=>readContext(0));el('context-next').onclick=guarded(()=>readContext(contextOffset||0));
document.querySelectorAll('[data-action]').forEach(b=>b.onclick=guarded(()=>action(b.dataset.action)));
el('feedback').onclick=guarded(async()=>{if(!shown)throw Error('没有待反馈版本');await action('feedback',{reference:shown.id,actor:el('actor').value,decision:el('decision').value,reason:el('reason').value});el('reason').value=''});
el('reconcile').onclick=guarded(()=>action('recover',{reconciliation:JSON.parse(el('reconciliation').value)}));
el('steer').onclick=guarded(async()=>{await action('steer',{text:el('direction').value,actor:el('actor').value});el('direction').value='' });
el('fork').onclick=guarded(async()=>{let r=await api('action',{session:sid(),action:'fork',budget:JSON.parse(el('budget').value)});await refresh();el('sessions').value=r.id;await refresh()});
el('read').onclick=guarded(async()=>show('artifact',await api('artifact'+query()+'&path='+encodeURIComponent(el('files').value))));
el('report-read').onclick=guarded(async()=>show('report',(await api('report'+query()+'&reference='+encodeURIComponent(el('reports').value))).markdown));
el('logs').onclick=guarded(async()=>show('logs-text',await api('logs'+query()+'&attempt='+encodeURIComponent(el('attempts').value))));
el('import').onclick=guarded(async()=>{let f=el('upload').files[0];if(!f)throw Error('先选择文件');if(f.size>16000000)throw Error('浏览器单文件上限 16 MB；更大材料请用 agent-create inputs');let raw=new Uint8Array(await f.arrayBuffer()),s='';for(let i=0;i<raw.length;i+=8192)s+=String.fromCharCode(...raw.subarray(i,i+8192));await action('import',{path:'inputs/'+f.name,base64:btoa(s),actor:el('actor').value})});
guarded(async()=>{let c=await api('catalog');show('count',c.skills.length+' 个技能 · '+c.operations.length+' 个原有科研工具');show('catalog',c);await refresh()})();setInterval(guarded(refresh),3000);
</script></html>'''
